from qb import q, write

FS = ["full-stack-developer", "backend-developer", "frontend-developer", "mobile-app-developer"]
ITEMS = [
    q("cloud", "easy", ["cloud-basics"], "What are IaaS, PaaS and SaaS? Give an example of each.", "IaaS gives raw infrastructure such as virtual machines, for example EC2. PaaS gives a managed platform to run your code, for example Heroku or Elastic Beanstalk. SaaS is a finished application, for example Gmail.", ["Three service levels", "More control to less control", "Example of each"], ["Which would you pick for a small startup and why?"]),
    q("cloud", "medium", ["aws"], "Explain what an AWS S3 bucket, an EC2 instance and an IAM role are and how they work together in a simple web application.", "EC2 runs your application code, S3 stores files such as images and backups, and an IAM role gives the EC2 instance permission to read and write S3 without storing access keys in code. Permissions follow least privilege.", ["Compute, storage, permissions", "Role instead of hard-coded keys", "Least privilege"], ["How would you serve files in S3 to users safely?"]),
    q("cloud", "hard", ["scalability"], "A web application slows down when traffic doubles. How would you scale it and what limits each approach?", "Scale vertically by using a bigger server, which is simple but limited, or horizontally by running several instances behind a load balancer, which needs stateless servers and shared sessions. Also cache, use a read replica and move slow work to queues, and find the real bottleneck first.", ["Vertical vs horizontal", "Stateless servers and a load balancer", "Cache, replicas, queues"], ["What makes an application hard to scale horizontally?"]),
    q("docker", "easy", ["containers"], "What is Docker and how is a container different from a virtual machine?", "Docker packages an application with its dependencies into an image that runs as a container. Containers share the host kernel and start quickly, while a virtual machine includes a full operating system and is heavier.", ["Image and container", "Shared kernel", "Lighter and faster than a VM"], ["What goes into a Dockerfile?"]),
    q("docker", "medium", ["docker-practice"], "How would you containerise a web application with a database for local development, and what should not go inside the image?", "Write a Dockerfile for the app and use Docker Compose to run it with a database container and a volume for data. Keep secrets, local data and unneeded build files out of the image, and pass configuration through environment variables.", ["Dockerfile and Compose", "Volume for database data", "No secrets in the image"], ["Why use a multi-stage build?"]),
    q("devops", "medium", ["ci-cd"], "Describe a CI/CD pipeline for a web project and what each stage protects against.", "On every push the pipeline installs dependencies, runs linting and tests, builds the app and then deploys to staging and, after approval or checks, to production. Tests catch regressions, the build catches broken packaging and staged deployment limits damage.", ["Lint, test, build, deploy", "Staging before production", "Automatic and repeatable"], ["How would you roll back a bad release?"]),
    q("architecture", "medium", ["microservices"], "What are microservices and what problems do they introduce compared with a monolith?", "Microservices split an application into small independently deployed services. They allow separate scaling and team ownership but add network failures, distributed data, harder debugging and deployment complexity, so a monolith is often better for small teams.", ["Small independent services", "Benefits: scaling and ownership", "Costs: distribution complexity"], ["How would services find and talk to each other?"]),
    q("architecture", "hard", ["api-gateway", "messaging"], "When would you use a message queue between services instead of a direct API call?", "Use a queue when the caller does not need an immediate answer, when the receiver can be slow or down, or to smooth traffic spikes. It decouples services but needs handling of duplicates, ordering and failed messages.", ["Asynchronous work", "Decoupling and buffering", "Duplicates and dead letters"], ["What is a dead-letter queue?"]),
    q("rest-api", "easy", ["http"], "What is the difference between PUT and PATCH and between authentication and authorisation?", "PUT replaces a whole resource and PATCH changes only some fields. Authentication proves who the user is and authorisation decides what that user is allowed to do.", ["PUT replaces, PATCH partially updates", "Who you are vs what you may do", "Both are needed"], ["Which HTTP status codes do you use for each failure?"]),
    q("rest-api", "medium", ["graphql"], "Compare REST and GraphQL and say when you would choose GraphQL.", "REST exposes resources at fixed endpoints, while GraphQL lets the client ask for exactly the fields it needs from one endpoint. GraphQL helps when clients need varied data shapes, but it adds caching and security complexity such as query depth limits.", ["Fixed endpoints vs flexible queries", "Avoids over-fetching", "Complexity: caching and limits"], ["What is the N+1 problem in GraphQL resolvers?"]),
    q("database", "easy", ["sql-nosql"], "What is the difference between SQL and NoSQL databases and how do you choose?", "SQL databases use tables with a fixed schema, relations and strong transactions, while NoSQL databases use flexible models such as documents or key-value pairs. Choose by data shape, consistency needs and how the data is queried.", ["Schema and relations vs flexibility", "Consistency needs", "Choose by access pattern"], ["Can one application use both?"]),
    q("database", "medium", ["indexing"], "How do you decide which columns to index and what is the cost of too many indexes?", "Index columns used in frequent filters, joins and sorting and that are selective enough to narrow results. Every extra index uses space and slows inserts and updates, so verify with query plans and remove unused ones.", ["Index filter, join and sort columns", "Selectivity matters", "Cost on writes and space"], ["What is a composite index?"]),
    q("database", "hard", ["migrations"], "How do you change a database table in production without downtime?", "Make changes backward compatible in steps: add the new column as nullable, deploy code that writes both, backfill old rows in batches, switch reads and only later remove the old column. Test on a copy and have a rollback.", ["Backward compatible steps", "Backfill in batches", "Remove the old column last"], ["Why can adding an index lock a big table?"]),
    q("javascript", "medium", ["async"], "Explain the difference between synchronous and asynchronous code and show how you would call two independent APIs in parallel.", "Synchronous code blocks until each step finishes, while asynchronous code lets other work run while waiting. Start both requests together and await them with Promise.all so the total time is about that of the slower call.", ["Blocking vs non-blocking", "Start both, then await", "Promise.all for independent calls"], ["How do you handle one of them failing?"]),
    q("react", "medium", ["forms"], "How would you build a form in React with validation and good error messages?", "Keep form values in state or a form library, validate on change or submit, show clear messages next to each field, disable the button while submitting and handle server errors. Also validate on the server because client checks can be bypassed.", ["Controlled inputs", "Clear field errors", "Server-side validation too"], ["How do you keep the form accessible?"]),
    q("mobile", "medium", ["app-release"], "What steps and risks are involved in releasing a mobile app update to the app stores?", "Build a signed release, test on real devices and versions, update the version number, submit for store review and roll out gradually. The risks are review delays, users on old versions and no instant rollback, so use feature flags and keep the API backward compatible.", ["Signed build and device testing", "Store review and staged rollout", "Old versions must keep working"], ["How would you force users off a broken version?"]),
    q("agile", "easy", ["scrum"], "Explain sprints, standups and retrospectives in Scrum.", "A sprint is a fixed period in which the team completes planned work. A standup is a short daily sync on progress and blockers, and a retrospective at the end looks at what went well and what to improve.", ["Time-boxed sprint", "Daily standup for blockers", "Retrospective to improve"], ["What would you do if you are blocked?"]),
    q("git", "medium", ["branching"], "A merge conflict appears in a pull request. How do you resolve it and avoid it in the future?", "Pull the latest target branch, open the conflicting files, decide which changes to keep with the other developer if needed, test, then commit the resolution. Keep branches small and short-lived and integrate often to reduce conflicts.", ["Understand both changes", "Resolve and test", "Small, frequent integration"], ["When would you use rebase instead of merge?"]),
    q("security", "medium", ["web-security"], "What is CORS and why does the browser block some cross-origin requests?", "The browser blocks scripts on one origin from reading responses from another unless the server allows it with CORS headers. This protects users from malicious sites using their logged-in session, and it must be configured with specific allowed origins, not a wildcard for credentialed requests.", ["Same-origin policy", "Server opts in with headers", "Avoid wildcard with credentials"], ["Is CORS a server security feature?"]),
    q("testing", "medium", ["test-strategy"], "How do you decide what to cover with unit tests, integration tests and end-to-end tests?", "Write many fast unit tests for logic, fewer integration tests for how parts such as the API and database work together, and a few end-to-end tests for critical user journeys. Higher-level tests are slower and more fragile.", ["Test pyramid", "Cost grows with scope", "Critical journeys end-to-end"], ["What would you do about a flaky test?"]),
    q("fullstack-scenario", "medium", ["debugging"], "Scenario: users report that saving a profile sometimes fails with an error but works for you. How do you track it down?", "Look at server logs and the failing requests, find a common factor such as input size, special characters or a particular account, reproduce with that data, fix the cause and add a test. Improve the error message and monitoring.", ["Find the pattern in failures", "Reproduce with real data", "Fix, test and add monitoring"], ["How would you add logging without leaking personal data?"], kind="scenario"),
    q("fullstack-scenario", "hard", ["design"], "Scenario: design a file upload feature for large videos that works on mobile networks.", "Upload directly to object storage with a signed URL in resumable chunks, so the app server is not overloaded and interrupted uploads can resume. Validate type and size, scan or process the file in the background and show progress.", ["Signed URL straight to storage", "Chunked resumable uploads", "Background processing and validation"], ["How would you stop users from uploading harmful files?"], kind="scenario"),
    q("python", "easy", ["python-basics"], "Compare how you would loop over a list of orders to total their prices in Python and in JavaScript, and what built-in helps in each.", "In Python use a for loop or sum with a generator expression, and in JavaScript use a for...of loop or reduce. Both are O(n) and the built-in helpers express the intent more clearly than manual index handling.", ["Loop or built-in helper", "sum in Python, reduce in JavaScript", "O(n) either way"], ["How do you avoid mutating the original list?"], roles=FS + ["python-developer"]),
    q("data-structures", "medium", ["hash-maps"], "How would you group a list of orders by customer and find the customer with the highest total?", "Use a dictionary keyed by customer that accumulates totals in one pass, then take the maximum of its values. This is O(n) and avoids repeated scans of the list.", ["Dictionary keyed by customer", "Accumulate in one pass", "Take the maximum"], ["What if two customers tie?"], roles=FS + ["python-developer"]),
    q("project", "easy", ["projects"], "Describe a full-stack or mobile project you built. How did the front end, back end and database communicate and what would you change?", "A strong answer explains the architecture and data flow, your own contribution, one problem such as authentication or deployment and its fix, and a realistic improvement such as tests or performance.", ["Clear data flow", "Own contribution", "Realistic improvement"], ["How is it deployed?"], kind="scenario", roles=FS + ["python-developer"]),
]


def build():
    return write("10pearls", FS, ITEMS)


if __name__ == "__main__":
    build()
